@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@700;800&family=Figtree:wght@400;600;700&display=swap');
:root{--primary:#1b8168;--primary-fg:#117b63;--primary-soft:#dcf5ec;--accent:#a9c24f;--accent-soft:#eaf2ce;--accent-fg:#56701f;--cream:#f4f8f0;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;--teal-soft:#d9ecec;--danger:#b23b3b;--danger-soft:#f6e4e2}
body{background:#e7ede4}
.phone{width:390px;max-width:100%;box-sizing:border-box;margin:24px auto;background:var(--cream);border-radius:32px;padding:20px 16px 28px;font-family:Figtree,system-ui,sans-serif;color:var(--ink);box-shadow:0 10px 40px rgba(0,0,0,.08);min-height:760px}
.top{display:flex;justify-content:space-between;font-size:14px;margin-bottom:14px}.top a{color:var(--primary-fg);font-weight:700;text-decoration:none}
h1{font-family:'Bricolage Grotesque',sans-serif;font-size:26px;line-height:1.15;font-weight:800;margin:0}
.sum{font-size:13px;color:var(--ink-soft);margin:6px 0 12px}
.toggle{display:flex;justify-content:space-between;align-items:center;background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:10px 14px;font-size:14px;margin-bottom:14px}
.sw{width:40px;height:24px;border-radius:12px;background:var(--primary);position:relative}.sw:after{content:'';position:absolute;right:3px;top:3px;width:18px;height:18px;border-radius:50%;background:#fff}
h2{font-size:16px;font-weight:700;margin:4px 0 10px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;list-style:none;padding:0;margin:0}
.card{background:var(--paper);border:1px solid var(--line);border-radius:20px;overflow:hidden;font-size:13px;position:relative}
.thumb{aspect-ratio:1;background:linear-gradient(135deg,#d9ecec,#eaf2ce);display:flex;align-items:center;justify-content:center;font-size:40px}
.cb{padding:8px 10px 10px}.name{font-weight:700;font-size:14px;margin-bottom:2px}.stan{color:var(--ink-soft);font-size:12px}
.pill{display:inline-block;margin-top:6px;padding:2px 9px;border-radius:999px;font-size:11px;font-weight:700;background:var(--primary-soft);color:var(--primary-fg)}
.pill.swap{background:var(--accent-soft);color:var(--accent-fg)}
.new{position:absolute;top:8px;left:8px;background:var(--primary);color:#fff;font-size:11px;font-weight:700;border-radius:999px;padding:2px 8px}
.missing{margin-top:6px;font-size:12px;color:var(--ink-soft)}.missing b{color:var(--ink);font-weight:700}
.skel .thumb{background:var(--line);animation:p 1.2s infinite}.skel .bar{height:10px;border-radius:5px;background:var(--line);margin:6px 0;animation:p 1.2s infinite}
@keyframes p{50%{opacity:.5}}
.pending{display:flex;align-items:center;gap:10px;background:var(--paper);border:1px solid var(--line);border-radius:20px;padding:14px;margin-bottom:14px;font-size:15px;font-weight:600}
.spin{width:22px;height:22px;border-radius:50%;border:3px solid var(--primary-soft);border-top-color:var(--primary);animation:r 1s linear infinite;flex:none;box-sizing:border-box}@keyframes r{to{transform:rotate(360deg)}}
.pending small{display:block;font-weight:400;color:var(--ink-soft);font-size:13px}
.empty{display:flex;flex-direction:column;align-items:center;gap:10px;border:1.5px dashed var(--line-strong);background:var(--paper);border-radius:28px;padding:24px 20px;text-align:center}
.bell{width:64px;height:64px;border-radius:24px;background:var(--accent-soft);color:var(--accent-fg);display:flex;align-items:center;justify-content:center;font-size:28px}
.empty h3{font-family:'Bricolage Grotesque',sans-serif;font-size:20px;font-weight:800;margin:0}.empty p{margin:0;color:var(--ink-soft);font-size:15px}
.sugg{margin-top:22px;border-top:1px solid var(--line);padding-top:16px}
.sugg h2{display:flex;gap:8px;align-items:center}.sugg .lead{font-size:13px;color:var(--ink-soft);margin:-4px 0 12px}
.sugg .card{border-style:dashed;border-color:var(--line-strong)}
.valid{font-size:13px;color:var(--ink-soft);margin:16px 0 10px}
.btn{display:block;box-sizing:border-box;width:100%;border-radius:16px;padding:13px;font-weight:700;font-size:15px;text-align:center;border:1.5px solid var(--line-strong);background:var(--paper);color:var(--ink);margin-bottom:10px}
.btn.primary{background:var(--primary);color:#fff;border-color:var(--primary)}
.row{display:flex;gap:10px}.row .btn{flex:1}.btn.danger{color:var(--danger)}
